/**
 * @file ir_protocols.c
 * @brief Table driven infrared protocol encoder/decoder engine.
 * @details Encoders emit mark/space microsecond pairs consumed by the
 *          irio_pio raw TX engine (upper 16 bits = mark, lower 16 bits =
 *          space, carrier generated by the TX PIO at the protocol carrier
 *          frequency). Decoders validate captured pair streams with
 *          tolerance based timing checks.
 *
 * Based on the INFRARED feature set of the ESP32-Bit-Pirate project
 * (https://github.com/geo-tp/ESP32-Bit-Pirate), adapted for the Bus Pirate 5.
 *
 * Modified for Bus Pirate 5 by community contributors (c) 2026
 * SPDX-License-Identifier: MIT
 */

#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <strings.h>
#include "pico/stdlib.h"
#include "pirate.h"
#include "mode/infrared-struct.h"
#include "pirate/irio_pio.h"
#include "pirate/ir_protocols.h"

// ---------------------------------------------------------------------------
// pair helpers
// ---------------------------------------------------------------------------

/** push one mark/space pair (microseconds), false on overflow */
static bool ir_push(uint32_t mark_us, uint32_t space_us, uint32_t *pairs, uint16_t *count) {
    if ((*count) >= IR_MAX_PAIRS || mark_us > 0xffff || space_us > 0xffff) {
        return false;
    }
    pairs[(*count)++] = (mark_us << 16) | space_us;
    return true;
}

/** tolerance based timing match, percentage with an absolute floor */
static bool ir_approx(uint32_t value, uint32_t target, uint8_t pct) {
    uint32_t tol = (target * pct) / 100;
    if (tol < 40) {
        tol = 40;
    }
    uint32_t diff = (value >= target) ? (value - target) : (target - value);
    return diff <= tol;
}

static bool ir_is_timeout(uint32_t us) {
    return us == 0xffff;
}

// ---------------------------------------------------------------------------
// manchester half-bit emitter (RC5/RC6)
// ---------------------------------------------------------------------------

typedef struct _half_emitter {
    uint32_t *pairs;
    uint16_t count;
    uint32_t pending_mark;
    uint32_t pending_space;
} half_emitter;

/**
 * @brief Accumulate one half-bit (carrier burst = mark) and flush complete pairs.
 * @details A pair is (mark, space) in that order. A space that arrives before
 *          any mark (e.g. the leading silence of an RC5 frame) is emitted as
 *          a pair with a zero-length mark (~3us hardware minimum, harmless).
 */
static bool ir_half_emit(half_emitter *e, bool mark, uint32_t us) {
    if (mark) {
        if (e->pending_space && !e->pending_mark) { // leading space: flush (0, space)
            if (!ir_push(0, e->pending_space, e->pairs, &e->count)) {
                return false;
            }
            e->pending_space = 0;
        }
        e->pending_mark += us;
    } else {
        e->pending_space += us;
        if (e->pending_mark) { // complete pair: mark then space
            if (!ir_push(e->pending_mark, e->pending_space, e->pairs, &e->count)) {
                return false;
            }
            e->pending_mark = 0;
            e->pending_space = 0;
        }
    }
    return true;
}

static bool ir_half_flush(half_emitter *e) {
    if (e->pending_mark || e->pending_space) {
        if (!ir_push(e->pending_mark, e->pending_space, e->pairs, &e->count)) {
            return false;
        }
        e->pending_mark = 0;
        e->pending_space = 0;
    }
    return true;
}

/**
 * @brief Split a captured pair stream into manchester half-cells.
 * @param pairs      captured pairs
 * @param count      number of pairs
 * @param half_us    half-bit period in microseconds
 * @param halves     output half types, true = mark (carrier burst)
 * @param max_halves size of the halves buffer
 * @return number of halves, 0 if the stream does not fit the cell grid
 */
static uint16_t ir_halves_parse(const uint32_t *pairs,
                                uint16_t count,
                                uint32_t half_us,
                                bool *halves,
                                uint16_t max_halves) {
    uint16_t total = 0;
    for (uint16_t i = 0; i < count; i++) {
        const uint32_t durations[2] = { pairs[i] >> 16, pairs[i] & 0xffff };
        for (uint8_t d = 0; d < 2; d++) {
            uint32_t us = durations[d];
            if (ir_is_timeout(us)) {
                return total; // end of frame
            }
            if (us == 0) {
                continue; // leading space pair
            }
            uint32_t cells = (us + (half_us / 2)) / half_us;
            if (cells == 0) {
                cells = 1;
            }
            uint32_t ideal = cells * half_us;
            uint32_t err = (us >= ideal) ? (us - ideal) : (ideal - us);
            if (err > (half_us * 35) / 100) {
                return 0; // does not fit the cell grid
            }
            for (uint32_t c = 0; c < cells; c++) {
                if (total >= max_halves) {
                    return 0;
                }
                halves[total++] = (d == 0); // mark?
            }
        }
    }
    return total;
}

// ---------------------------------------------------------------------------
// NEC (and NEC extended addresses)
// ---------------------------------------------------------------------------

#define NEC_HDR_MARK 9000u
#define NEC_HDR_SPACE 4500u
#define NEC_RPT_SPACE 2250u
#define NEC_BIT_MARK 560u
#define NEC_ZERO_SPACE 560u
#define NEC_ONE_SPACE 1690u

static bool nec_encode(uint32_t dev, uint32_t sub, uint32_t cmd, uint32_t *pairs, uint16_t *count) {
    (void)sub;
    *count = 0;
    if (!ir_push(NEC_HDR_MARK, NEC_HDR_SPACE, pairs, count)) {
        return false;
    }
    uint32_t addr_bits = (dev <= 0xff) ? ((dev & 0xff) | ((~dev & 0xff) << 8)) : (dev & 0xffff);
    uint32_t cmd_bits = (cmd & 0xff) | ((~cmd & 0xff) << 8);
    uint32_t frame = addr_bits | (cmd_bits << 16);
    for (uint8_t i = 0; i < 32; i++) {
        uint32_t space = ((frame >> i) & 1) ? NEC_ONE_SPACE : NEC_ZERO_SPACE;
        if (!ir_push(NEC_BIT_MARK, space, pairs, count)) {
            return false;
        }
    }
    return ir_push(NEC_BIT_MARK, 20000, pairs, count); // trailer + gap
}

static bool nec_decode(const uint32_t *pairs, uint16_t count, uint32_t *dev, uint32_t *sub, uint32_t *cmd) {
    if (count < 3) {
        return false;
    }
    uint32_t mark0 = pairs[0] >> 16;
    uint32_t space0 = pairs[0] & 0xffff;
    if (!ir_approx(mark0, NEC_HDR_MARK, 25)) {
        return false;
    }
    if (ir_approx(space0, NEC_RPT_SPACE, 25)) { // repeat frame (button held)
        *dev = IR_REPEAT_FRAME;
        *sub = 0;
        *cmd = IR_REPEAT_FRAME;
        return true;
    }
    if (!ir_approx(space0, NEC_HDR_SPACE, 25)) {
        return false;
    }
    uint32_t value = 0;
    uint16_t i = 1;
    for (uint8_t bit = 0; bit < 32; bit++, i++) {
        if (i >= count) {
            return false;
        }
        uint32_t m = pairs[i] >> 16;
        uint32_t s = pairs[i] & 0xffff;
        if (!ir_approx(m, NEC_BIT_MARK, 35)) {
            return false;
        }
        if (ir_approx(s, NEC_ZERO_SPACE, 35)) {
            continue; // bit already 0
        } else if (ir_approx(s, NEC_ONE_SPACE, 35)) {
            value |= (1ul << bit);
        } else {
            return false;
        }
    }
    uint8_t addr_lo = value & 0xff;
    uint8_t addr_hi = (value >> 8) & 0xff;
    uint8_t cmd_lo = (value >> 16) & 0xff;
    uint8_t cmd_hi = (value >> 24) & 0xff;
    if (cmd_hi != (uint8_t)(~cmd_lo & 0xff)) {
        return false;
    }
    // 8 bit address + inverted, or 16 bit extended address
    *dev = (addr_lo == (uint8_t)(~addr_hi & 0xff)) ? addr_lo : (value & 0xffff);
    *sub = 0;
    *cmd = cmd_lo;
    return true;
}

// ---------------------------------------------------------------------------
// SONY SIRC (12/15/20 bit, pulse width encoded, LSB first)
// ---------------------------------------------------------------------------

#define SONY_HDR_MARK 2400u
#define SONY_SPACE 600u
#define SONY_ZERO_MARK 600u
#define SONY_ONE_MARK 1200u

static bool sony_encode(uint32_t dev, uint32_t sub, uint32_t cmd, uint32_t *pairs, uint16_t *count) {
    (void)sub;
    *count = 0;
    uint8_t addr_bits = (dev <= 0x1f) ? 5 : (dev <= 0xff) ? 8 : 13;
    uint8_t total = 7 + addr_bits;
    uint32_t frame = ((dev & ((1ul << addr_bits) - 1)) << 7) | (cmd & 0x7f);
    if (!ir_push(SONY_HDR_MARK, SONY_SPACE, pairs, count)) {
        return false;
    }
    for (uint8_t i = 0; i < total; i++) {
        uint32_t mark = ((frame >> i) & 1) ? SONY_ONE_MARK : SONY_ZERO_MARK;
        uint32_t space = (i == (total - 1)) ? 15000 : SONY_SPACE; // gap after the last mark
        if (!ir_push(mark, space, pairs, count)) {
            return false;
        }
    }
    return true;
}

static bool sony_decode(const uint32_t *pairs, uint16_t count, uint32_t *dev, uint32_t *sub, uint32_t *cmd) {
    if (count < 13) {
        return false;
    }
    if (!ir_approx(pairs[0] >> 16, SONY_HDR_MARK, 25) || !ir_approx(pairs[0] & 0xffff, SONY_SPACE, 35)) {
        return false;
    }
    // bits are pulse width encoded: the mark carries the value, the space is
    // a fixed 600us (except after the last mark, where the frame times out)
    uint32_t value = 0;
    uint16_t i = 1;
    while (i < count) {
        uint32_t m = pairs[i] >> 16;
        uint32_t s = pairs[i] & 0xffff;
        bool bit;
        if (ir_approx(m, SONY_ZERO_MARK, 30)) {
            bit = false;
        } else if (ir_approx(m, SONY_ONE_MARK, 30)) {
            bit = true;
        } else {
            break;
        }
        value |= (bit ? 1ul : 0ul) << (i - 1);
        i++;
        if (!ir_approx(s, SONY_SPACE, 35)) {
            break; // frame end (timeout or gap)
        }
    }
    uint16_t nbits = i - 1;
    if (nbits != 12 && nbits != 15 && nbits != 20) {
        return false;
    }
    *dev = (value >> 7) & ((1ul << (nbits - 7)) - 1);
    *sub = nbits; // report SIRC flavour
    *cmd = value & 0x7f;
    return true;
}

// ---------------------------------------------------------------------------
// RC5 / RC5X (14 bits, manchester, MSB first, 889us half-bit)
// wire convention from rc5.pio: '0' = burst then silence, '1' = silence then burst
// ---------------------------------------------------------------------------

#define RC5_HALF 889u

static bool rc5_encode(uint32_t dev, uint32_t sub, uint32_t cmd, uint32_t *pairs, uint16_t *count) {
    *count = 0;
    uint32_t cmd6 = cmd & 0x3f;
    uint32_t s2 = 1;
    if (cmd > 0x3f) { // RC5X: second start bit carries inverted command bit 6
        s2 = ((cmd >> 6) & 1) ? 0 : 1;
    }
    uint32_t frame = (1ul << 13) | (s2 << 12) | ((sub ? 1 : 0) << 11) | ((dev & 0x1f) << 6) | cmd6;
    half_emitter e = { .pairs = pairs, .count = 0, .pending_mark = 0, .pending_space = 0 };
    for (uint8_t i = 0; i < 14; i++) { // MSB first
        bool bit = (frame >> (13 - i)) & 1;
        // '1' = silence then burst, '0' = burst then silence
        if (!ir_half_emit(&e, !bit, RC5_HALF) || !ir_half_emit(&e, bit, RC5_HALF)) {
            return false;
        }
    }
    if (!ir_half_emit(&e, false, 20000)) { // trailing gap
        return false;
    }
    if (!ir_half_flush(&e)) {
        return false;
    }
    *count = e.count;
    return true;
}

static bool rc5_decode(const uint32_t *pairs, uint16_t count, uint32_t *dev, uint32_t *sub, uint32_t *cmd) {
    bool halves[32];
    uint16_t n = ir_halves_parse(pairs, count, RC5_HALF, halves, 32);
    if (n < 26) {
        // capture starts at the first burst and the trailing half-bit of a
        // frame ending in silence is lost to the RX timeout: 26..27 halves
        return false;
    }
    if (n < 27) {
        halves[n] = !halves[n - 1]; // infer the lost trailing half by alternation
        n++;
    }
    // bit i uses the halves at grid positions 2i and 2i+1. The captured stream
    // starts with the burst half of start bit S1, so the (always silent) first
    // half of S1 is virtual and prepended below.
    uint32_t frame = 0;
    for (uint8_t i = 0; i < 14; i++) {
        bool first = (i == 0) ? false : halves[(2 * i) - 1];
        bool second = halves[2 * i];
        if (!first && second) {
            frame |= (1ul << (13 - i)); // '1' = silence then burst
        } else if (!(first && !second)) {
            return false;
        }
    }
    if (!((frame >> 13) & 1)) { // S1 must be 1
        return false;
    }
    *dev = (frame >> 6) & 0x1f;
    *sub = (frame >> 11) & 1; // toggle bit
    uint32_t c = frame & 0x3f;
    if (!((frame >> 12) & 1)) { // RC5X: S2 = inverted command bit 6
        c |= 0x40;
    }
    *cmd = c;
    return true;
}

// ---------------------------------------------------------------------------
// RC6 mode 0 (16 data bits, manchester 444us, MSB first)
// '0' = burst then silence, '1' = silence then burst (opposite polarity of RC5)
// ---------------------------------------------------------------------------

#define RC6_HALF 444u
#define RC6_HDR_MARK 2666u

static bool rc6_encode(uint32_t dev, uint32_t sub, uint32_t cmd, uint32_t *pairs, uint16_t *count) {
    (void)sub;
    *count = 0;
    half_emitter e = { .pairs = pairs, .count = 0, .pending_mark = 0, .pending_space = 0 };
    // header: 6 cell mark, 2 cell space
    if (!ir_half_emit(&e, true, 6 * RC6_HALF) || !ir_half_emit(&e, false, 2 * RC6_HALF)) {
        return false;
    }
    // doubled '1' start bit: 2 cell space (merges with the header space on the
    // wire) followed by a 2 cell mark
    if (!ir_half_emit(&e, false, 2 * RC6_HALF) || !ir_half_emit(&e, true, 2 * RC6_HALF)) {
        return false;
    }
    // mode bits 000 ('0' = mark then space)
    for (uint8_t i = 0; i < 3; i++) {
        if (!ir_half_emit(&e, true, RC6_HALF) || !ir_half_emit(&e, false, RC6_HALF)) {
            return false;
        }
    }
    // doubled '1' trailer bit: 2 cell space then 2 cell mark
    if (!ir_half_emit(&e, false, 2 * RC6_HALF) || !ir_half_emit(&e, true, 2 * RC6_HALF)) {
        return false;
    }
    uint32_t frame = ((dev & 0xff) << 8) | (cmd & 0xff); // MSB first
    for (uint8_t i = 0; i < 16; i++) {
        bool bit = (frame >> (15 - i)) & 1;
        // '0' = mark then space, '1' = space then mark
        if (!ir_half_emit(&e, !bit, RC6_HALF) || !ir_half_emit(&e, bit, RC6_HALF)) {
            return false;
        }
    }
    if (!ir_half_emit(&e, false, 2666)) {
        return false;
    }
    if (!ir_half_flush(&e)) {
        return false;
    }
    *count = e.count;
    return true;
}

static bool rc6_decode(const uint32_t *pairs, uint16_t count, uint32_t *dev, uint32_t *sub, uint32_t *cmd) {
    (void)sub;
    if (count < 12) {
        return false;
    }
    if (!ir_approx(pairs[0] >> 16, RC6_HDR_MARK, 25)) {
        return false;
    }
    uint32_t hdr_space = pairs[0] & 0xffff;
    if (!ir_approx(hdr_space, 4 * RC6_HALF, 25)) { // header space + doubled start bit space
        return false;
    }
    bool halves[64];
    uint16_t n = ir_halves_parse(&pairs[1], count - 1, RC6_HALF, halves, 64);
    if (n < 43) {
        // start(2) + mode(6) + trailer(4) + data(32) halves; the trailing
        // half-bit of a frame ending in silence is lost to the RX timeout
        return false;
    }
    if (n < 44) {
        halves[n] = !halves[n - 1]; // infer the lost trailing half by alternation
        n++;
    }
    // blind pair the halves into bit cells
    if (!(halves[0] && halves[1])) {
        return false; // start bit (remaining halves)
    }
    for (uint8_t i = 0; i < 3; i++) {
        if (!halves[2 + 2 * i] || halves[3 + 2 * i]) {
            return false; // mode bits must be 000 ('0' = mark then space)
        }
    }
    if (halves[8] || halves[9] || !halves[10] || !halves[11]) {
        return false; // trailer bit ('1' doubled: space space mark mark)
    }
    uint32_t frame = 0;
    for (uint8_t i = 0; i < 16; i++) {
        bool first = halves[12 + 2 * i];
        bool second = halves[13 + 2 * i];
        if (!first && second) {
            frame |= (1ul << (15 - i)); // '1' = silence then burst
        } else if (!(first && !second)) {
            return false;
        }
    }
    *dev = (frame >> 8) & 0xff;
    *sub = 0;
    *cmd = frame & 0xff;
    return true;
}

// ---------------------------------------------------------------------------
// SAMSUNG (Samsung32, 32 bits, LSB first)
// ---------------------------------------------------------------------------

#define SAMSUNG_HDR_MARK 4500u
#define SAMSUNG_HDR_SPACE 4500u
#define SAMSUNG_BIT_MARK 560u
#define SAMSUNG_ZERO_SPACE 560u
#define SAMSUNG_ONE_SPACE 1690u

static bool samsung_encode(uint32_t dev, uint32_t sub, uint32_t cmd, uint32_t *pairs, uint16_t *count) {
    (void)sub;
    *count = 0;
    if (!ir_push(SAMSUNG_HDR_MARK, SAMSUNG_HDR_SPACE, pairs, count)) {
        return false;
    }
    uint32_t frame = (dev & 0xff) | ((dev & 0xff) << 8) | ((cmd & 0xff) << 16) | ((~cmd & 0xff) << 24);
    for (uint8_t i = 0; i < 32; i++) {
        uint32_t space = ((frame >> i) & 1) ? SAMSUNG_ONE_SPACE : SAMSUNG_ZERO_SPACE;
        if (!ir_push(SAMSUNG_BIT_MARK, space, pairs, count)) {
            return false;
        }
    }
    return ir_push(SAMSUNG_BIT_MARK, 15000, pairs, count);
}

static bool samsung_decode(const uint32_t *pairs, uint16_t count, uint32_t *dev, uint32_t *sub, uint32_t *cmd) {
    if (count < 34) {
        return false;
    }
    if (!ir_approx(pairs[0] >> 16, SAMSUNG_HDR_MARK, 25) || !ir_approx(pairs[0] & 0xffff, SAMSUNG_HDR_SPACE, 25)) {
        return false;
    }
    uint32_t value = 0;
    for (uint8_t bit = 0; bit < 32; bit++) {
        uint32_t m = pairs[bit + 1] >> 16;
        uint32_t s = pairs[bit + 1] & 0xffff;
        if (!ir_approx(m, SAMSUNG_BIT_MARK, 35)) {
            return false;
        }
        if (ir_approx(s, SAMSUNG_ONE_SPACE, 35)) {
            value |= (1ul << bit);
        } else if (!ir_approx(s, SAMSUNG_ZERO_SPACE, 35)) {
            return false;
        }
    }
    uint8_t addr = value & 0xff;
    uint8_t addr2 = (value >> 8) & 0xff;
    uint8_t cmd_lo = (value >> 16) & 0xff;
    uint8_t cmd_hi = (value >> 24) & 0xff;
    if (addr != addr2 || cmd_hi != (uint8_t)(~cmd_lo & 0xff)) {
        return false;
    }
    *dev = addr;
    *sub = 0;
    *cmd = cmd_lo;
    return true;
}

// ---------------------------------------------------------------------------
// LG (28 bits, LSB first)
// ---------------------------------------------------------------------------

#define LG_HDR_MARK 8000u
#define LG_HDR_SPACE 4000u
#define LG_BIT_MARK 600u
#define LG_ZERO_SPACE 550u
#define LG_ONE_SPACE 1600u

static bool lg_encode(uint32_t dev, uint32_t sub, uint32_t cmd, uint32_t *pairs, uint16_t *count) {
    (void)sub;
    *count = 0;
    if (!ir_push(LG_HDR_MARK, LG_HDR_SPACE, pairs, count)) {
        return false;
    }
    uint32_t frame = (dev & 0xff) | ((~dev & 0x0f) << 8) | ((cmd & 0xff) << 12) | ((~cmd & 0xff) << 20);
    for (uint8_t i = 0; i < 28; i++) {
        uint32_t space = ((frame >> i) & 1) ? LG_ONE_SPACE : LG_ZERO_SPACE;
        if (!ir_push(LG_BIT_MARK, space, pairs, count)) {
            return false;
        }
    }
    return ir_push(LG_BIT_MARK, 15000, pairs, count);
}

static bool lg_decode(const uint32_t *pairs, uint16_t count, uint32_t *dev, uint32_t *sub, uint32_t *cmd) {
    if (count < 30) {
        return false;
    }
    if (!ir_approx(pairs[0] >> 16, LG_HDR_MARK, 25) || !ir_approx(pairs[0] & 0xffff, LG_HDR_SPACE, 25)) {
        return false;
    }
    uint32_t value = 0;
    for (uint8_t bit = 0; bit < 28; bit++) {
        uint32_t m = pairs[bit + 1] >> 16;
        uint32_t s = pairs[bit + 1] & 0xffff;
        if (!ir_approx(m, LG_BIT_MARK, 35)) {
            return false;
        }
        if (ir_approx(s, LG_ONE_SPACE, 35)) {
            value |= (1ul << bit);
        } else if (!ir_approx(s, LG_ZERO_SPACE, 35)) {
            return false;
        }
    }
    uint8_t addr = value & 0xff;
    uint8_t cmd_lo = (value >> 12) & 0xff;
    uint8_t cmd_hi = (value >> 20) & 0xff;
    if ((uint8_t)((value >> 8) & 0x0f) != (uint8_t)(~addr & 0x0f)) {
        return false;
    }
    if (cmd_hi != (uint8_t)(~cmd_lo & 0xff)) {
        return false;
    }
    *dev = addr;
    *sub = 0;
    *cmd = cmd_lo;
    return true;
}

// ---------------------------------------------------------------------------
// JVC (16 bits, LSB first)
// ---------------------------------------------------------------------------

#define JVC_HDR_MARK 8400u
#define JVC_HDR_SPACE 4200u
#define JVC_BIT_MARK 525u
#define JVC_ZERO_SPACE 525u
#define JVC_ONE_SPACE 1575u

static bool jvc_encode(uint32_t dev, uint32_t sub, uint32_t cmd, uint32_t *pairs, uint16_t *count) {
    (void)sub;
    *count = 0;
    if (!ir_push(JVC_HDR_MARK, JVC_HDR_SPACE, pairs, count)) {
        return false;
    }
    uint32_t frame = (dev & 0xff) | ((cmd & 0xff) << 8);
    for (uint8_t i = 0; i < 16; i++) {
        uint32_t space = ((frame >> i) & 1) ? JVC_ONE_SPACE : JVC_ZERO_SPACE;
        if (!ir_push(JVC_BIT_MARK, space, pairs, count)) {
            return false;
        }
    }
    return ir_push(JVC_BIT_MARK, 10000, pairs, count);
}

static bool jvc_decode(const uint32_t *pairs, uint16_t count, uint32_t *dev, uint32_t *sub, uint32_t *cmd) {
    if (count < 18) {
        return false;
    }
    if (!ir_approx(pairs[0] >> 16, JVC_HDR_MARK, 25) || !ir_approx(pairs[0] & 0xffff, JVC_HDR_SPACE, 25)) {
        return false;
    }
    uint32_t value = 0;
    for (uint8_t bit = 0; bit < 16; bit++) {
        uint32_t m = pairs[bit + 1] >> 16;
        uint32_t s = pairs[bit + 1] & 0xffff;
        if (!ir_approx(m, JVC_BIT_MARK, 35)) {
            return false;
        }
        if (ir_approx(s, JVC_ONE_SPACE, 35)) {
            value |= (1ul << bit);
        } else if (!ir_approx(s, JVC_ZERO_SPACE, 35)) {
            return false;
        }
    }
    *dev = value & 0xff;
    *sub = 0;
    *cmd = (value >> 8) & 0xff;
    return true;
}

// ---------------------------------------------------------------------------
// PANASONIC / Kaseikyo (48 bits, LSB first) - Arduino IRremote compatible
// [0:16) vendor ID, [16:20) vendor parity nibble, [20:32) 12 bit address,
// [32:40) function, [40:48) parity = function ^ byte2 ^ byte3
// ---------------------------------------------------------------------------

#define PANASONIC_HDR_MARK 3456u
#define PANASONIC_HDR_SPACE 1728u
#define PANASONIC_BIT_MARK 432u
#define PANASONIC_ZERO_SPACE 432u
#define PANASONIC_ONE_SPACE 1296u
#define PANASONIC_VENDOR_CODE 0x4004ul

static bool panasonic_encode(uint32_t dev, uint32_t sub, uint32_t cmd, uint32_t *pairs, uint16_t *count) {
    *count = 0;
    uint16_t vendor = (uint16_t)PANASONIC_VENDOR_CODE;
    // 12 bit address, Bit-Pirate packAddress() compatible: (sub << 8) | device
    uint16_t address = (uint16_t)((((sub & 0x0f) << 8) | (dev & 0xff)) & 0x0fff);
    uint8_t vendor_parity = (uint8_t)((vendor ^ (vendor >> 8)) & 0xff);
    vendor_parity = (uint8_t)((vendor_parity ^ (vendor_parity >> 4)) & 0x0f);
    uint8_t b3 = (uint8_t)(((address & 0x0f) << 4) | vendor_parity); // low byte of address + vendor parity
    uint8_t b4 = (uint8_t)(address >> 4);                            // high byte of address
    uint8_t b5 = (uint8_t)(cmd & 0xff);                              // function
    uint8_t b6 = (uint8_t)(b5 ^ b3 ^ b4);                            // parity
    uint64_t frame = (uint64_t)vendor | ((uint64_t)b3 << 16) | ((uint64_t)b4 << 24) |
                     ((uint64_t)b5 << 32) | ((uint64_t)b6 << 40);
    if (!ir_push(PANASONIC_HDR_MARK, PANASONIC_HDR_SPACE, pairs, count)) {
        return false;
    }
    for (uint8_t i = 0; i < 48; i++) {
        uint32_t space = ((frame >> i) & 1) ? PANASONIC_ONE_SPACE : PANASONIC_ZERO_SPACE;
        if (!ir_push(PANASONIC_BIT_MARK, space, pairs, count)) {
            return false;
        }
    }
    return ir_push(PANASONIC_BIT_MARK, 15000, pairs, count);
}

static bool panasonic_decode(const uint32_t *pairs, uint16_t count, uint32_t *dev, uint32_t *sub, uint32_t *cmd) {
    if (count < 50) {
        return false;
    }
    if (!ir_approx(pairs[0] >> 16, PANASONIC_HDR_MARK, 25) || !ir_approx(pairs[0] & 0xffff, PANASONIC_HDR_SPACE, 25)) {
        return false;
    }
    uint64_t value = 0;
    for (uint8_t bit = 0; bit < 48; bit++) {
        uint32_t m = pairs[bit + 1] >> 16;
        uint32_t s = pairs[bit + 1] & 0xffff;
        if (!ir_approx(m, PANASONIC_BIT_MARK, 35)) {
            return false;
        }
        if (ir_approx(s, PANASONIC_ONE_SPACE, 35)) {
            value |= ((uint64_t)1 << bit);
        } else if (!ir_approx(s, PANASONIC_ZERO_SPACE, 35)) {
            return false;
        }
    }
    uint16_t vendor = (uint16_t)(value & 0xffff);
    uint8_t b3 = (uint8_t)((value >> 16) & 0xff);
    uint8_t b4 = (uint8_t)((value >> 24) & 0xff);
    uint8_t b5 = (uint8_t)((value >> 32) & 0xff);
    uint8_t b6 = (uint8_t)((value >> 40) & 0xff);
    if (b6 != (uint8_t)(b5 ^ b3 ^ b4)) {
        return false;
    }
    (void)vendor;
    uint16_t address = (uint16_t)(((b4 << 4) | (b3 >> 4)) & 0x0fff);
    *dev = address & 0xff;            // device
    *sub = (address >> 8) & 0x0f;     // sub-device
    *cmd = b5;                        // function
    return true;
}

// ---------------------------------------------------------------------------
// SHARP (15 bits sent twice: normal then inverted address, LSB first, no header)
// ---------------------------------------------------------------------------

#define SHARP_BIT_MARK 320u
#define SHARP_ZERO_SPACE 680u
#define SHARP_ONE_SPACE 1680u
#define SHARP_GAP_SPACE 6000u

static bool sharp_encode(uint32_t dev, uint32_t sub, uint32_t cmd, uint32_t *pairs, uint16_t *count) {
    (void)sub;
    *count = 0;
    uint32_t frames[2] = {
        ((dev & 0x1f)) | ((cmd & 0xff) << 5) | (0x01ul << 13),
        ((~dev & 0x1f)) | ((cmd & 0xff) << 5) | (0x02ul << 13),
    };
    for (uint8_t f = 0; f < 2; f++) {
        for (uint8_t i = 0; i < 15; i++) {
            uint32_t space = ((frames[f] >> i) & 1) ? SHARP_ONE_SPACE : SHARP_ZERO_SPACE;
            if (!ir_push(SHARP_BIT_MARK, space, pairs, count)) {
                return false;
            }
        }
        uint32_t gap = (f == 0) ? SHARP_GAP_SPACE : 15000;
        if (!ir_push(SHARP_BIT_MARK, gap, pairs, count)) {
            return false;
        }
    }
    return true;
}

static bool sharp_decode(const uint32_t *pairs, uint16_t count, uint32_t *dev, uint32_t *sub, uint32_t *cmd) {
    (void)sub;
    if (count < 31) {
        return false;
    }
    uint32_t values[2] = { 0, 0 };
    uint16_t i = 0;
    for (uint8_t f = 0; f < 2; f++) {
        for (uint8_t bit = 0; bit < 15; bit++, i++) {
            if (i >= count) {
                return false;
            }
            uint32_t m = pairs[i] >> 16;
            uint32_t s = pairs[i] & 0xffff;
            if (!ir_approx(m, SHARP_BIT_MARK, 35)) {
                return false;
            }
            if (ir_approx(s, SHARP_ONE_SPACE, 30)) {
                values[f] |= (1ul << bit);
            } else if (!ir_approx(s, SHARP_ZERO_SPACE, 30)) {
                return false;
            }
        }
        if (f == 0) { // inter-frame gap
            if (i >= count || !ir_approx(pairs[i] >> 16, SHARP_BIT_MARK, 35) ||
                !ir_approx(pairs[i] & 0xffff, SHARP_GAP_SPACE, 40)) {
                return false;
            }
            i++;
        }
    }
    uint8_t addr1 = values[0] & 0x1f;
    uint8_t addr2 = values[1] & 0x1f;
    if (addr2 != (uint8_t)(~addr1 & 0x1f)) {
        return false;
    }
    if (((values[0] >> 13) & 0x3) != 0x01 || ((values[1] >> 13) & 0x3) != 0x02) {
        return false;
    }
    if (((values[0] >> 5) & 0xff) != ((values[1] >> 5) & 0xff)) {
        return false;
    }
    *dev = addr1;
    *sub = 0;
    *cmd = (values[0] >> 5) & 0xff;
    return true;
}

// ---------------------------------------------------------------------------
// DISH (16 bits, LSB first, inverted data, no header, ~57.6kHz carrier)
// ---------------------------------------------------------------------------

#define DISH_BIT_MARK 400u
#define DISH_ZERO_SPACE 266u
#define DISH_ONE_SPACE 800u

static bool dish_encode(uint32_t dev, uint32_t sub, uint32_t cmd, uint32_t *pairs, uint16_t *count) {
    (void)sub;
    *count = 0;
    uint32_t frame = (~((dev & 0x0f) | ((cmd & 0x3ff) << 4))) & 0xffff;
    for (uint8_t i = 0; i < 16; i++) {
        uint32_t space = ((frame >> i) & 1) ? DISH_ONE_SPACE : DISH_ZERO_SPACE;
        if (!ir_push(DISH_BIT_MARK, space, pairs, count)) {
            return false;
        }
    }
    return ir_push(DISH_BIT_MARK, 15000, pairs, count);
}

static bool dish_decode(const uint32_t *pairs, uint16_t count, uint32_t *dev, uint32_t *sub, uint32_t *cmd) {
    if (count < 17) {
        return false;
    }
    uint32_t value = 0;
    for (uint8_t bit = 0; bit < 16; bit++) {
        uint32_t m = pairs[bit] >> 16;
        uint32_t s = pairs[bit] & 0xffff;
        if (!ir_approx(m, DISH_BIT_MARK, 20)) {
            return false;
        }
        if (ir_approx(s, DISH_ONE_SPACE, 30)) {
            value |= (1ul << bit);
        } else if (!ir_approx(s, DISH_ZERO_SPACE, 30)) {
            return false;
        }
    }
    value = ~value & 0xffff;
    *dev = value & 0x0f;
    *sub = 0;
    *cmd = (value >> 4) & 0x3ff;
    return true;
}

// ---------------------------------------------------------------------------
// protocol table (order = decode priority)
// ---------------------------------------------------------------------------

static const ir_protocol_def_t ir_protocol_table[] = {
    { .display = "NEC", .arg_name = "nec", .carrier_hz = 38000, .bits = 32, .default_repeats = 3,
        .encode = nec_encode, .decode = nec_decode },
    { .display = "SAMSUNG", .arg_name = "samsung", .carrier_hz = 38000, .bits = 32, .default_repeats = 3,
        .encode = samsung_encode, .decode = samsung_decode },
    { .display = "LG", .arg_name = "lg", .carrier_hz = 38000, .bits = 28, .default_repeats = 3,
        .encode = lg_encode, .decode = lg_decode },
    { .display = "SONY", .arg_name = "sony", .carrier_hz = 40000, .bits = 12, .default_repeats = 3,
        .encode = sony_encode, .decode = sony_decode },
    { .display = "JVC", .arg_name = "jvc", .carrier_hz = 38000, .bits = 16, .default_repeats = 3,
        .encode = jvc_encode, .decode = jvc_decode },
    { .display = "PANASONIC", .arg_name = "panasonic", .carrier_hz = 37000, .bits = 48, .default_repeats = 3,
        .encode = panasonic_encode, .decode = panasonic_decode },
    { .display = "RC5", .arg_name = "rc5", .carrier_hz = 36000, .bits = 14, .default_repeats = 3,
        .encode = rc5_encode, .decode = rc5_decode },
    { .display = "RC6", .arg_name = "rc6", .carrier_hz = 36000, .bits = 16, .default_repeats = 3,
        .encode = rc6_encode, .decode = rc6_decode },
    { .display = "DISH", .arg_name = "dish", .carrier_hz = 57600, .bits = 16, .default_repeats = 3,
        .encode = dish_encode, .decode = dish_decode },
    { .display = "SHARP", .arg_name = "sharp", .carrier_hz = 38000, .bits = 15, .default_repeats = 3,
        .encode = sharp_encode, .decode = sharp_decode },
};

uint8_t ir_protocols_count(void) {
    return count_of(ir_protocol_table);
}

const ir_protocol_def_t *ir_protocols_get(uint8_t idx) {
    if (idx >= count_of(ir_protocol_table)) {
        return &ir_protocol_table[0];
    }
    return &ir_protocol_table[idx];
}

int8_t ir_protocols_find(const char *arg_name) {
    for (uint8_t i = 0; i < count_of(ir_protocol_table); i++) {
        if (strcasecmp(arg_name, ir_protocol_table[i].arg_name) == 0) {
            return (int8_t)i;
        }
    }
    return -1;
}

bool ir_protocols_send(uint8_t idx, uint32_t dev, uint32_t sub, uint32_t cmd, uint8_t repeats) {
    if (idx >= count_of(ir_protocol_table)) {
        return false;
    }
    const ir_protocol_def_t *proto = &ir_protocol_table[idx];
    if (repeats == 0) {
        repeats = proto->default_repeats;
    }
    uint32_t pairs[IR_MAX_PAIRS];
    uint16_t count;
    for (uint8_t r = 0; r < repeats; r++) {
        count = 0;
        if (!proto->encode(dev, sub, cmd, pairs, &count)) {
            return false;
        }
        irio_pio_tx_frame_write((float)proto->carrier_hz, count, pairs);
        if (r < (repeats - 1)) {
            busy_wait_us(30000); // inter-frame gap on top of the encoded tail
        }
    }
    return true;
}

bool ir_protocols_decode(const uint32_t *pairs, uint16_t count, int8_t *idx, uint32_t *dev, uint32_t *sub, uint32_t *cmd) {
    *idx = -1;
    for (uint8_t i = 0; i < count_of(ir_protocol_table); i++) {
        if (ir_protocol_table[i].decode(pairs, count, dev, sub, cmd)) {
            *idx = (int8_t)i;
            return true;
        }
    }
    return false;
}
